-- Create "workflow_user_settings" table
CREATE TABLE "workflow_user_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "mail" boolean NOT NULL DEFAULT true, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "workflow_user_settings_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE);
-- Create index "workflow_user_settings_user" to table: "workflow_user_settings"
CREATE UNIQUE INDEX "workflow_user_settings_user" ON "workflow_user_settings" ("user_id");
